<template>
  <main class="project-page">
    <aside class="filter-sidebar">
      <button class="brand" @click="router.push('/dashboard')"><i>D</i><span><b>Dokiai Academic</b><small>PROJECT CENTER</small></span></button>
      <div class="filter-title"><small>PROJECT LIBRARY</small><h2>历史项目</h2><p>{{ filteredProjects.length }} 个项目</p></div>
      <label class="search"><i>⌕</i><input v-model="keyword" placeholder="搜索项目名称"></label>
      <section><strong>项目状态</strong><button v-for="item in statusFilters" :key="item.value" :class="{active:statusFilter===item.value}" @click="statusFilter=item.value"><span>{{ item.label }}</span><em>{{ countStatus(item.value) }}</em></button></section>
      <section><strong>专业类型</strong><select v-model="majorFilter"><option value="all">全部专业</option><option v-for="item in majors" :key="item" :value="item">{{ item }}</option></select></section>
      <section><strong>更新时间</strong><select v-model="timeFilter"><option value="all">全部时间</option><option value="7">最近 7 天</option><option value="30">最近 30 天</option><option value="90">最近 90 天</option></select></section>
      <section class="folders"><strong>项目文件夹</strong><button class="active"><span>◇ 全部项目</span></button><button disabled><span>＋ 新建文件夹</span><small>待接入</small></button></section>
      <button class="back" @click="router.push('/dashboard')">← 返回工作台</button>
    </aside>

    <section class="project-content">
      <header class="page-head"><div><span>DOKIAI PROJECT CENTER</span><h1>我的历史项目</h1><p>查找、继续并管理每一个学术创作项目。</p></div><button class="primary" @click="router.push('/writing-generator')">＋ 创建新项目</button></header>
      <div v-if="selectedIds.length" class="batch-bar"><strong>已选择 {{ selectedIds.length }} 项</strong><button @click="unsupported('批量归档')">归档</button><button @click="batchDownload">下载</button><button @click="unsupported('批量删除')">删除</button><button @click="unsupported('生成 ZIP')">生成 ZIP</button><button class="clear" @click="selectedIds=[]">取消选择</button></div>
      <div class="toolbar"><div><button :class="{active:viewMode==='grid'}" @click="viewMode='grid'">▦ 卡片</button><button :class="{active:viewMode==='list'}" @click="viewMode='list'">☷ 列表</button></div><span>按更新时间排序</span></div>

      <div v-if="filteredProjects.length" :class="['project-grid',viewMode]">
        <article v-for="project in filteredProjects" :key="projectKey(project)" :class="['project-card',majorClass(project),{selected:selectedIds.includes(projectKey(project))}]" @click="openDetail(project)">
          <header><label @click.stop><input type="checkbox" :checked="selectedIds.includes(projectKey(project))" @change="toggleSelect(project)"><i></i></label><span>{{ projectMajor(project) }}</span><details @click.stop><summary>•••</summary><div><button @click="unsupported('重命名')">重命名</button><button @click="unsupported('克隆项目')">克隆</button><button @click="unsupported('移动到文件夹')">移动到文件夹</button><button class="danger" @click="unsupported('删除项目')">删除</button></div></details></header>
          <div class="card-body"><small>{{ formatTime(projectTime(project)) }}</small><h2>{{ projectName(project) }}</h2><p>{{ statusText(project.status) }} · {{ stepLabel(project) }}</p></div>
          <div class="progress"><label><span>{{ stepLabel(project) }}</span><strong>{{ projectProgress(project) }}%</strong></label><i><b :style="{width:projectProgress(project)+'%'}"></b></i></div>
          <div class="file-stats"><span><b>{{ project.referenceCount??project.reference_count??'--' }}</b>文献</span><span><b>{{ project.imageCount??project.image_count??'--' }}</b>图片</span><span><b>{{ project.fileCount??project.file_count??(project.downloadAvailable?1:0) }}</b>文件</span></div>
          <footer><button class="continue" @click.stop="continueProject(project)">继续项目 →</button><button class="download" :disabled="!downloadUrl(project)" @click.stop="downloadProject(project)">↓ 下载</button></footer>
        </article>
      </div>
      <div v-else class="empty"><i>◇</i><h2>没有符合条件的项目</h2><p>调整筛选条件，或创建一个新的文档项目。</p><button class="primary" @click="router.push('/writing-generator')">创建新项目</button></div>

      <section class="project-insight"><div><small>PROJECT INSIGHT</small><h2>项目工作流概览</h2><p>所有项目均按文献、结构、素材、写作、导出五个阶段统一管理。</p></div><div class="workflow"><span v-for="(step,index) in stepNames" :key="step"><i>{{ index+1 }}</i><b>{{ step }}</b></span></div></section>
    </section>

    <transition name="drawer"><aside v-if="detailProject" class="detail-drawer"><header><div><small>PROJECT DETAILS</small><h2>{{ projectName(detailProject) }}</h2></div><button @click="detailProject=null">×</button></header><div class="detail-meta"><span><small>专业</small><b>{{ projectMajor(detailProject) }}</b></span><span><small>状态</small><b>{{ statusText(detailProject.status) }}</b></span><span><small>更新时间</small><b>{{ formatTime(projectTime(detailProject)) }}</b></span><span><small>项目 ID</small><b>{{ projectKey(detailProject) }}</b></span></div><section><small>WORKFLOW</small><h3>五步进度</h3><article v-for="(step,index) in stepNames" :key="step"><i :class="{done:index+1<=stepIndex(detailProject)}">{{ index+1<=stepIndex(detailProject)?'✓':index+1 }}</i><span><b>{{ step }}</b><small>{{ index+1<stepIndex(detailProject)?'已完成':index+1===stepIndex(detailProject)?'当前阶段':'等待开始' }}</small></span><em>{{ index+1<stepIndex(detailProject)?'100%':index+1===stepIndex(detailProject)?'进行中':'0%' }}</em></article></section><section><small>FILE VERSIONS</small><h3>文件版本</h3><div v-if="downloadUrl(detailProject)" class="version"><i>W</i><span><b>{{ detailProject.fileName||`${projectName(detailProject)}.docx` }}</b><small>最新交付版本</small></span><button @click="downloadProject(detailProject)">下载</button></div><p v-else class="muted">尚无可下载版本</p></section><section><small>ACTIVITY</small><h3>最近操作</h3><div class="log"><i>●</i><span><b>{{ statusText(detailProject.status) }}</b><small>{{ formatTime(projectTime(detailProject)) }}</small></span></div></section><footer><button class="primary" @click="continueProject(detailProject)">继续项目</button></footer></aside></transition>
    <div v-if="detailProject" class="drawer-mask" @click="detailProject=null"></div>
  </main>
</template>

<script setup>
import { computed,onMounted,ref } from 'vue';import { ElMessage } from 'element-plus';import { useRouter } from 'vue-router';import { downloadArtifact,downloadPptFile,getMyDocuments,getWritingProjectHistory,listPptProjects } from '../../api/rewrite'
const router=useRouter(),projects=ref([]),keyword=ref(''),statusFilter=ref('all'),majorFilter=ref('all'),timeFilter=ref('all'),selectedIds=ref([]),detailProject=ref(null),viewMode=ref('grid');const stepNames=['文献研究','结构设计','素材管理','AI 写作','DOCX 导出'];const statusFilters=[{label:'全部项目',value:'all'},{label:'进行中',value:'active'},{label:'已完成',value:'success'},{label:'需要处理',value:'failed'}]
const majors=computed(()=>[...new Set(projects.value.map(projectMajor))]);const filteredProjects=computed(()=>projects.value.filter(p=>{const matchKeyword=projectName(p).toLowerCase().includes(keyword.value.trim().toLowerCase()),matchStatus=statusFilter.value==='all'||statusFilter.value==='success'&&p.status==='SUCCESS'||statusFilter.value==='failed'&&p.status==='FAILED'||statusFilter.value==='active'&&!['SUCCESS','FAILED'].includes(p.status),matchMajor=majorFilter.value==='all'||projectMajor(p)===majorFilter.value;let matchTime=true;if(timeFilter.value!=='all'){const date=new Date(projectTime(p));matchTime=!Number.isNaN(date.getTime())&&(Date.now()-date.getTime())<=Number(timeFilter.value)*86400000}return matchKeyword&&matchStatus&&matchMajor&&matchTime}));
function isPpt(p){return p.projectKind==='PPT_GENERATE'}function projectKey(p){return String(p.projectId||p.id||p.fileName)}function projectName(p){return p.projectName||p.topic||p.title||p.fileName||'未命名项目'}function projectMajor(p){if(isPpt(p))return p.major||'PPT生成';const raw=p.documentType||p.projectType||p.document_mode||'智能文档';return({environment:'环境设计',visual_communication:'视觉传达',interior_design:'室内设计',general:'普通论文'})[raw]||raw}function projectTime(p){return p.updateTime||p.updated_at||p.updatedAt||p.createdTime||p.createTime||p.created_at||p.createdAt}function formatTime(v){return v?String(v).replace('T',' ').slice(0,16):'--'}function statusText(v){return({SUCCESS:'已完成',FAILED:'需要处理',RUNNING:'生成中',GENERATING:'生成中',WAITING:'待继续',PENDING:'排队中',DRAFT:'待上传',UPLOADED:'待解析',ANALYZED:'内容已解析',OUTLINE_READY:'目录待确认',PLANNED:'等待生成'})[v]||v||'进行中'}function stepIndex(p){if(isPpt(p))return Math.max(1,Math.min(5,Math.ceil(Number(p.progress||0)/20)));const explicit=Number(p.stepIndex||p.step_index);if(explicit>=1&&explicit<=5)return explicit;if(p.status==='SUCCESS')return 5;if(['RUNNING','GENERATING'].includes(p.status))return 4;if(p.currentStep){const idx=stepNames.findIndex(x=>String(p.currentStep).includes(x.replace('AI ','')));if(idx>=0)return idx+1}return p.status==='WAITING'?2:1}function projectProgress(p){return isPpt(p)?Number(p.progress||0):stepIndex(p)*20}function stepLabel(p){return isPpt(p)?`PPT生成 · ${p.current_stage||statusText(p.status)}`:`Step ${stepIndex(p)} · ${stepNames[stepIndex(p)-1]}`}function downloadUrl(p){return isPpt(p)?(p.output_path?'ppt':''):p.downloadUrl||p.download_url||''}function majorClass(p){const v=projectMajor(p);return v.includes('环境')?'environment':v.includes('视觉')?'visual':v.includes('室内')?'interior':'general'}function countStatus(v){if(v==='all')return projects.value.length;return projects.value.filter(p=>v==='success'?p.status==='SUCCESS':v==='failed'?p.status==='FAILED':!['SUCCESS','FAILED'].includes(p.status)).length}
function openDetail(p){detailProject.value=p}function toggleSelect(p){const id=projectKey(p);selectedIds.value=selectedIds.value.includes(id)?selectedIds.value.filter(x=>x!==id):[...selectedIds.value,id]}function unsupported(name){ElMessage.info(`${name}需要后端项目管理接口，当前未执行任何数据修改`)}function routeForStep(step){return['/writing-generator','/writing-generator/outline','/writing-generator/materials','/writing-generator/generate','/writing-generator/export'][step-1]||'/writing-generator'}function continueProject(p){if(isPpt(p))return router.push({path:'/ppt-generator',query:{projectId:projectKey(p)}});sessionStorage.setItem('dropai_writing_project_id',projectKey(p));router.push(routeForStep(stepIndex(p)))}async function downloadProject(p){if(!downloadUrl(p))return ElMessage.warning('最新版文件尚未生成');try{const blob=isPpt(p)?await downloadPptFile(projectKey(p)):await downloadArtifact(downloadUrl(p)),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=isPpt(p)?`${projectName(p)}.pptx`:p.fileName||`${projectName(p)}.docx`;a.click();URL.revokeObjectURL(url)}catch(e){ElMessage.error(e.message||'下载失败')}}async function batchDownload(){const list=projects.value.filter(p=>selectedIds.value.includes(projectKey(p))&&downloadUrl(p));if(!list.length)return ElMessage.warning('所选项目没有可下载文件');for(const item of list)await downloadProject(item)}
async function load(){try{const [history,docs,ppts]=await Promise.all([getWritingProjectHistory().catch(()=>[]),getMyDocuments({pageNum:1,pageSize:100}).catch(()=>({list:[]})),listPptProjects().catch(()=>[])]),map=new Map();[...(history||[]),...(docs?.list||[]),...(ppts||[]).map(x=>({...x,projectKind:'PPT_GENERATE'}))].forEach(item=>{const key=(item.projectKind||'DOC')+projectKey(item),old=map.get(key)||{};map.set(key,{...old,...item})});projects.value=[...map.values()].sort((a,b)=>new Date(projectTime(b)||0)-new Date(projectTime(a)||0))}catch(e){ElMessage.warning(e?.responseData?.message||e.message||'项目列表暂时无法读取')}}onMounted(load)
</script>

